"{
  "name": "alphaforge-backend",
  "version": "1.0.0",
  "description": "AlphaForge AI — ARGUS Backend (Express + Gemini)",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js",
    "test": "echo \"No tests configured yet\" && exit 0"
  },
  "dependencies": {
    "@google/generative-ai": "^0.21.0",
    "axios": "^1.7.7",
    "cors": "^2.8.5",
    "dotenv": "^16.4.5",
    "express": "^4.21.0",
    "express-rate-limit": "^7.4.1",
    "helmet": "^8.0.0",
    "morgan": "^1.10.0",
    "uuid": "^10.0.0",
    "zod": "^3.23.8"
  },
  "devDependencies": {
    "nodemon": "^3.1.7"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
"

"/**
 * Environment configuration loader and validator.
 * All environment variables are accessed through this module — never directly from process.env.
 * This ensures a single place for validation and defaults.
 */

const dotenv = require('dotenv');
dotenv.config();

const config = {
  // Server
  port: parseInt(process.env.PORT, 10) || 5000,
  nodeEnv: process.env.NODE_ENV || 'development',
  isDev: (process.env.NODE_ENV || 'development') === 'development',

  // Gemini LLM
  gemini: {
    apiKey: process.env.GEMINI_API_KEY || '',
    model: process.env.GEMINI_MODEL || 'gemini-1.5-flash',
  },

  // Alpha Vantage (Financial Data)
  alphaVantage: {
    apiKey: process.env.ALPHA_VANTAGE_API_KEY || '',
    baseUrl: process.env.ALPHA_VANTAGE_BASE_URL || 'https://www.alphavantage.co/query',
  },

  // NewsAPI
  newsApi: {
    apiKey: process.env.NEWS_API_KEY || '',
    baseUrl: process.env.NEWS_API_BASE_URL || 'https://newsapi.org/v2',
  },

  // Financial Modeling Prep (fallback)
  fmp: {
    apiKey: process.env.FMP_API_KEY || '',
    baseUrl: process.env.FMP_BASE_URL || 'https://financialmodelingprep.com/api/v3',
  },

  // CORS
  frontendUrl: process.env.FRONTEND_URL || 'http://localhost:5173',

  // Rate limiting
  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 900000,
    max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100,
  },

  // Analysis settings
  analysis: {
    maxRetries: parseInt(process.env.MAX_RETRIES, 10) || 2,
    timeoutMs: parseInt(process.env.REQUEST_TIMEOUT_MS, 10) || 15000,
  },
};

/**
 * Checks if an API key is actually configured (not the placeholder value).
 */
config.hasGeminiKey = () => Boolean(config.gemini.apiKey && config.gemini.apiKey !== 'your_gemini_api_key_here');
config.hasAlphaVantageKey = () => Boolean(config.alphaVantage.apiKey && config.alphaVantage.apiKey !== 'your_alpha_vantage_key_here');
config.hasNewsApiKey = () => Boolean(config.newsApi.apiKey && config.newsApi.apiKe
