"/**
 * Navbar Component
 * Integrates logo, navigation links, light/dark theme switcher, and ARGUS status.
 * Wrapped in try-catch blocks to prevent SecurityErrors in sandboxed browser environments.
 */

import React, { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

const Navbar = () => {
  const location = useLocation();
  const isDashboard = location.pathname === '/dashboard';

  const [theme, setTheme] = useState(() => {
    try {
      return localStorage.getItem('theme') || 'dark';
    } catch {
      return 'dark';
    }
  });

  useEffect(() => {
    // Apply theme class
    if (theme === 'light') {
      document.documentElement.classList.add('light');
    } else {
      document.documentElement.classList.remove('light');
    }

    try {
      localStorage.setItem('theme', theme);
    } catch {
      // Fail-safe for sandboxed environments
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 border-b border-slate-700/20 backdrop-blur-md transition-colors duration-300" 
