"/**
 * ChatWindow — Follow-up chat with ARGUS
 * Fully themed component using CSS variables for light/dark mode compatibility.
 */
import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { sendChatMessage } from '../services/apiClient';

const Message = ({ role, content, confidence }) => {
  const isUser = role === 'user';
  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
      className={`flex gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>
      <div className="w-7 h-7 rounded-lg flex items-center justify-center flex-shrink-0 text-xs font-bold border transition-colors duration-300"
        style={isUser
          ? { backgroundColor: 'var(--graphite-light)', borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }
          : { background: 'linear-gradient(135deg, #10b981, #06b6d4)', borderColor: 'transparent', color: '#0a0f1e' }}>
        {isUser ? 'U' : 'A'}
      </div>
      <div className={`max-w-[80%] rounded-xl px-4 py-3 border transition-colors duration-300 ${isUser ? 'rounded-tr-none' : 'rounded-tl-none'}`}
        style={isUser
          ? { backgroundColor: 'var(--navy-light)', borderColor: 'var(--border-color)', color: 'var(--text-primary)' }
          : { backgroundColor: 'var(--graphite)', borderColor: 'var(--border-color)', color: 'var(--text-primary)' }}>
        <p className="text-sm leading-relaxed whitespace-pre-wrap">{content}</p>
        {!isUser && confidence !== undefined && (
          <p className="text-xs text-slate-500 mt-1.5 font-mono">Confidence: {confidence}%</p>
        )}
      </div>
    </motion.div>
  );
};

const QUICK_QUESTIONS = [
  'Should I invest now?',
  'What are the biggest risks?',
  'How does it compare to competitors?',
