"/**
 * Navbar Component
 * Integrates logo, navigation links, light/dark theme switcher, and ARGUS status.
 * Wrapped in try-catch blocks and uses a module-level session variable to guarantee
 * theme persistence across route changes even when localStorage is blocked.
 */

import React, { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

// Module-level state to persist theme during React Router navigation in sandboxed browsers
let globalTheme = 'dark';
try {
  globalTheme = localStorage.getItem('theme') || 'dark';
} catch {
  // sandboxed environment fallback
}

const Navbar = () => {
  const location = useLocation();
  const isDashboard = location.pathname === '/dashboard';

  const [theme, setTheme] = useState(globalTheme);

  useEffect(() => {
    globalTheme = theme;

    // Apply theme class to document element
    if (theme === 'light') {
      document.documentElement.classList.add('light');
    } else {
      document.documentElement.classList.remove('light');
    }

    try {
      localStorage.setItem('theme', theme);
    } catch {
      // Fail-safe for sandboxed environments
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
