1: /**
2:  * Fallback Engine
3:  * Per Engineering Constitution Article 11: Application failures must never terminate analysis.
4:  * Strategy: Primary → Retry → Partial Result → Reduce Confidence → Continue
5:  * 
6:  * Individual tool failures are ISOLATED. Other tools continue running.
7:  * User always receives a report, even if partial.
8:  */
9: 
10: const logger = require('../utils/logger');
11: const config = require('../config/env');
12: 
13: /**
14:  * Executes a function with retry logic.
15:  * If all retries fail, returns the fallback value (null/empty) and marks as failed.
16:  * 
17:  * @param {Function} fn - Async function to execute
18:  * @param {string} toolName - Name for logging
19:  * @param {*} fallbackValue - Value to return if all retries fail
20:  * @returns {Promise<{ data: *, failed: boolean, error: string|null }>}
21:  */
22: const withFallback = async (fn, toolName, fallbackValue = null) => {
23:   const maxRetries = config.analysis.maxRetries;
24: 
25:   for (let attempt = 1; attempt <= maxRetries; attempt++) {
26:     try {
27:       logger.debug(`[FallbackEngine] ${toolName} — attempt ${attempt}/${maxRetries}`);
28:       const data = await fn();
29:       logger.info(`[FallbackEngine] ${toolName} — succeeded on attempt ${attempt}`);
30:       return { data, failed: false, error: null };
31:     } catch (err) {
32:       logger.warn(`[FallbackEngine] ${toolName} — attempt ${attempt} failed: ${err.message}`);
33: 
34:       if (attempt === maxRetries) {
35:         logger.error(`[FallbackEngine] ${toolName} — all retries exhausted, using fallback`);
36:         return {
37:           data: fallbackValue,
38:           failed: true,
39:           error: err.message,
40:         };
41:       }
42: 
43:       // Brief wait before retry
44:       await new Promise((resolve) => setTimeout(resolve, 1000 * attempt));
45:     }
46:   }
47: };
48: 
49: /**
50:  * Runs all tool functions in parallel using Promise.allSettled.
51:  * This ensures one tool failure does NOT block other tools.
52:  * Returns results map with { data, failed, error } for each tool.
53:  * 
54:  * @param {object} tools - Map of { toolName: asyncFunction }
55:  * @returns {Promise<object>} - Map of { toolName: { data, failed, error } }
56:  */
57: const runToolsInParallel = async (tools) => {
58:   const toolNames = Object.keys(tools);
59:   const toolFunctions = Object.values(tools);
60: 
61:   logger.info(`[FallbackEngine] Running ${toolNames.length} tools in parallel: ${toolNames.join(', ')}`);
62: 
63:   const results = await Promise.allSettled(
64:     toolFunctions.map((fn, i) => withFallback(fn, toolNames[i]))
65:   );
