"const { GoogleGenerativeAI } = require('@google/generative-ai');
const { OpenAI } = require('openai');
const { Groq } = require('groq-sdk');
const dotenv = require('dotenv');
const path = require('path');

// Load environment variables
dotenv.config({ path: path.join(__dirname, '.env') });

async function checkGemini() {
  const key = process.env.GEMINI_API_KEY;
  if (!key) return { success: false, reason: 'Key not found in .env' };

  try {
    const client = new GoogleGenerativeAI(key);
    const model = client.getGenerativeModel({ model: 'gemini-1.5-flash' });
    await model.generateContent('ping');
    return { success: true };
  } catch (err) {
    let reason = err.message;
    if (key.substring(0, 6) !== 'AIzaSy') {
      reason += ' (Note: Google AI Studio keys must start with "AIzaSy" - your key starts with "' + key.substring(0, 3) + '")';
    }
    return { success: false, reason };
  }
}

async function checkOpenAI() {
  const key = process.env.OPENAI_API_KEY;
  if (!key) return { success: false, reason: 'Key not found in .env' };

  try {
    const client = new OpenAI({ apiKey: key });
    await client.chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [{ role: 'user', content: 'ping' }],
      max_tokens: 5
    });
    return { success: true };
  } catch (err) {
    return { success: false, reason: err.message };
  }
}

async function checkGroq() {
  const key = process.env.GROQ_API_KEY;
  if (!key) return { success: false, reason: 'Key not found in .env' };

  try {
    const client = new Groq({ apiKey: key });
    await client.chat.completions.create({
      model: 'llama-3.3-70b-versatile',
      messages: [{ role: 'user', content: 'ping' }],
      max_tokens: 5
    });
    return { success: true };
  } catch (err) {
    return { success: false, reason: err.message };
  }
}

async function runDiagnostics() {
  console.log('=== AlphaForge AI API Diagnostics ===\n');

  console.log('1. Testing Gemini...');
