9: /**
10:  * Computes the Levenshtein distance between two strings.
11:  * @param {string} a 
12:  * @param {string} b 
13:  * @returns {number} Distance score (lower is closer)
14:  */
15: function getLevenshteinDistance(a, b) {
16:   const matrix = [];
17: 
18:   for (let i = 0; i <= b.length; i++) matrix[i] = [i];
19:   for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
20: 
21:   for (let i = 1; i <= b.length; i++) {
22:     for (let j = 1; j <= a.length; j++) {
23:       if (b.charAt(i - 1) === a.charAt(j - 1)) {
24:         matrix[i][j] = matrix[i - 1][j - 1];
25:       } else {
26:         matrix[i][j] = Math.min(
27:           matrix[i - 1][j - 1] + 1, // substitution
28:           matrix[i][j - 1] + 1,     // insertion
29:           matrix[i - 1][j] + 1      // deletion
30:         );
31:       }
32:     }
33:   }
34: 
35:   return matrix[b.length][a.length];
36: }
